-- 593 · Legal module sample documents: a small sample PDF on every demo record that has a document field
-- (ID proofs, land record copies, enrolment certificates, land maps and deeds, enquiry papers, RS / LR copies,
-- the hold letter). Each PDF is stamped "SAMPLE - FOR TESTING ONLY - NOT A LEGAL DOCUMENT".
-- Stored like every Legal upload: in dbo.LegalMasterFile (base64), linked by id. A record that already has a
-- document is left alone, so the script is safe to run again.
SET NOCOUNT ON;
GO
IF EXISTS (SELECT 1 FROM dbo.LegalPerson WHERE PersonRole = N'Owner' AND FullName = N'Anirban Ghosh' AND IdProofFileId IS NULL)
BEGIN
  INSERT INTO dbo.LegalMasterFile (FileName, MimeType, FileSize, FileBase64, UploadedBy)
  VALUES (N'SAMPLE-Owner-Anirban-ID-proof.pdf', N'application/pdf', 1043, N'', (SELECT MIN(id) FROM dbo.users));
  UPDATE dbo.LegalPerson SET IdProofFileId = SCOPE_IDENTITY() WHERE PersonRole = N'Owner' AND FullName = N'Anirban Ghosh' AND IdProofFileId IS NULL;
END;
GO
